css:
.familyfin-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2c2418;
    background: linear-gradient(160deg, #f7f3ea 0%, #efe7d6 100%);
    border-radius: 18px;
}

.familyfin-container * {
    box-sizing: border-box;
}

.familyfin-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1e4d3a 0%, #2f6b4f 55%, #3f8a5e 100%);
    color: #f6f2e7;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(30, 77, 58, 0.30);
}

.familyfin-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.familyfin-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #e7d2a0;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.familyfin-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ecf2e7;
}

.familyfin-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #355a44;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.familyfin-period-counter #currentDay,
.familyfin-period-counter #maxPeriods {
    font-weight: 800;
    color: #1e4d3a;
}

.familyfin-round-name {
    background: #d9e8dd;
    color: #1e4d3a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.familyfin-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4a1c;
    background: #f6e3d2;
    padding: 4px 12px;
    border-radius: 999px;
}

.familyfin-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.familyfin-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e4dcc8;
    box-shadow: 0 4px 14px rgba(30, 77, 58, 0.06);
    border-top: 4px solid #3f8a5e;
}

.familyfin-card-liquidity { border-top-color: #2f6b4f; }
.familyfin-card-health { border-top-color: #2c6e8f; }
.familyfin-card-family { border-top-color: #b07c1f; }
.familyfin-card-bank { border-top-color: #6a4a9c; }

.familyfin-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 700;
    color: #8a7c5e;
}

.familyfin-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1e4d3a;
}

.familyfin-card-liquidity .familyfin-value { color: #2f6b4f; }
.familyfin-card-health .familyfin-value { color: #2c6e8f; }
.familyfin-card-family .familyfin-value { color: #b07c1f; }
.familyfin-card-bank .familyfin-value { color: #6a4a9c; }

.familyfin-sublabel {
    font-size: 0.75rem;
    color: #9a8c6c;
    line-height: 1.35;
}

.familyfin-card-warn .familyfin-value { color: #c0392b; }
.familyfin-card-good .familyfin-value { color: #2f6b4f; }

.familyfin-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1e4d3a;
    color: #eef5ee;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.familyfin-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7d2a0;
}

.familyfin-budget-over #budgetDisplay { color: #f3b8aa; }

.familyfin-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #3f8a5e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(30, 77, 58, 0.05);
}

.familyfin-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.familyfin-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1e4d3a;
    margin-bottom: 6px;
}

.familyfin-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a402c;
}

.familyfin-briefing-text strong { color: #2f6b4f; }
.familyfin-briefing-text em { color: #9a4a1c; font-style: italic; }

.familyfin-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e4dcc8;
    box-shadow: 0 4px 14px rgba(30, 77, 58, 0.06);
}

.familyfin-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1e4d3a;
    border-bottom: 2px solid #efe7d6;
    padding-bottom: 8px;
}

.familyfin-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a3120;
    margin: 14px 0 6px;
}

.familyfin-container select,
.familyfin-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d7cba8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdfbf5;
    color: #2c2418;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.familyfin-container select:focus,
.familyfin-container input[type="number"]:focus {
    outline: none;
    border-color: #3f8a5e;
    box-shadow: 0 0 0 3px rgba(63, 138, 94, 0.15);
}

.familyfin-container select option {
    background-color: #fffdf8;
    color: #2c2418;
}

.familyfin-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #3f8a5e;
}

.familyfin-range-readout,
.familyfin-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #355a44;
    margin-top: 4px;
}

.familyfin-range-readout span:last-child,
.familyfin-alloc-readout span:nth-child(2) {
    color: #2f6b4f;
    font-weight: 800;
}

.familyfin-hint {
    font-size: 0.8rem;
    color: #9a8c6c;
    margin-top: 4px;
    line-height: 1.4;
}

.familyfin-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.familyfin-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f1e4;
    border: 1px solid #e6ddc6;
    border-radius: 9px;
    padding: 8px 12px;
}

.familyfin-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #3a3120;
}

.familyfin-alloc-row input[type="number"] {
    width: 120px;
    flex: 0 0 120px;
}

.familyfin-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.familyfin-container .btn-primary {
    background: linear-gradient(135deg, #2f6b4f 0%, #3f8a5e 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(47, 107, 79, 0.28);
}

.familyfin-container .btn-primary:hover {
    filter: brightness(1.06);
}

.familyfin-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d7cba8;
    color: #8a7c5e;
}

.familyfin-coach {
    background: #1e4d3a;
    color: #eef5ee;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(30, 77, 58, 0.22);
}

.familyfin-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fc9a5;
    margin-bottom: 8px;
}

.familyfin-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.familyfin-coach-body strong { color: #f0d79b; }
.familyfin-coach-body em { color: #f3c1a6; font-style: italic; }

.familyfin-history,
.familyfin-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e4dcc8;
    box-shadow: 0 4px 14px rgba(30, 77, 58, 0.06);
}

.familyfin-history h3,
.familyfin-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1e4d3a;
}

.familyfin-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a3120;
}

.familyfin-container table#usfHistoryTable th {
    background: #eef0e3;
    color: #1e4d3a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #dde2cf;
}

.familyfin-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ece0;
}

.familyfin-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f1;
}

.familyfin-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .familyfin-container {
        padding: 14px;
    }
    .familyfin-header h1 {
        font-size: 1.7rem;
    }
    .familyfin-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .familyfin-value {
        font-size: 2rem;
    }
    .familyfin-clock {
        margin-left: 0;
    }
    .familyfin-period-counter {
        font-size: 0.88rem;
    }
    .familyfin-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .familyfin-alloc-row {
        flex-wrap: wrap;
    }
    .familyfin-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .familyfin-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion debrief — self-contained, append-only. Family Firm Finance palette. */
.ffsim-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #22301f; text-align: center; padding: 4px 2px 8px; }
.ffsim-cm-title { font-size: 20px; font-weight: 700; color: #1e4d3a; margin-bottom: 14px; }
.ffsim-cm-scorewrap { background: linear-gradient(135deg, #1e4d3a 0%, #2f6b4f 55%, #3f8a5e 100%); color: #fffdf8; border-radius: 14px; padding: 18px 16px; margin: 0 auto 16px; max-width: 420px; }
.ffsim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; }
.ffsim-cm-score-max { font-size: 20px; font-weight: 600; opacity: 0.85; }
.ffsim-cm-grade { font-size: 18px; font-weight: 700; margin-top: 8px; }
.ffsim-cm-badges { margin-top: 10px; }
.ffsim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; padding: 4px 12px; border-radius: 999px; }
.ffsim-cm-badge-ok { background: #d3e8d6; color: #1e4d3a; }
.ffsim-cm-badge-miss { background: #f6dcd2; color: #9a2f17; }
.ffsim-cm-kpis { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin: 0 auto 14px; max-width: 520px; }
.ffsim-cm-kpi { flex: 1 1 108px; min-width: 108px; background: #f7f3ea; border: 1px solid #e4dcc8; border-radius: 10px; padding: 10px 6px; }
.ffsim-cm-kpi-val { font-size: 20px; font-weight: 700; color: #1e4d3a; }
.ffsim-cm-kpi-lbl { font-size: 11px; font-weight: 600; color: #5c5a44; text-transform: uppercase; letter-spacing: .3px; margin-top: 2px; }
.ffsim-cm-insights { text-align: left; max-width: 540px; margin: 0 auto; background: #fffdf8; border-left: 4px solid #3f8a5e; border-radius: 8px; padding: 12px 16px; }
.ffsim-cm-ins-h { font-weight: 700; color: #1e4d3a; margin-bottom: 6px; font-size: 14px; }
.ffsim-cm-insights ul { margin: 0; padding-left: 18px; }
.ffsim-cm-insights li { font-size: 13px; line-height: 1.5; margin-bottom: 6px; color: #2b3626; }
@media (max-width: 480px) { .ffsim-cm-kpi { flex-basis: 40%; } .ffsim-cm-score { font-size: 38px; } .ffsim-cm-scorewrap { max-width: 100%; } }

