(function() {
    'use strict';

    class FamilyFinAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Family Firm Finance`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // NUMBERS REFERENCE CARD (COP millones).
            this.REQUIREMENT = 28200;      // total cash requirement
            this.CAPEX = 22000;            // plant + cold-chain
            this.WC_TRAP = 6200;           // working-capital trap from 75-day terms
            this.CASH = 5500;              // cash on hand
            this.FCF = 6800;               // free cash flow / year
            this.DIVIDEND = 6000;          // dividends / year (~88% payout)
            this.EBITDA = 12480;           // 13% of 96000
            this.START_LEVERAGE = 1.1;     // current debt/EBITDA
            this.COVENANT = 3.0;           // covenant ceiling
            this.LEV_PER_1000 = 0.08;      // ~0.08x per COP$1000M of new debt

            // Targets / starting KPIs (mirror view defaults; keep low for headroom).
            this.START = { liquidity: 20, health: 30, family: 25, bank: 15 };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    liquidity: this.START.liquidity,
                    health: this.START.health,
                    family: this.START.family,
                    bank: this.START.bank,
                    funded: 0,             // COP millones of requirement financed (committed capital)
                    leverage: this.START_LEVERAGE,
                    covenantBreach: false,
                    insolvent: false,
                    liquidityHistory: [this.START.liquidity],
                    healthHistory: [this.START.health],
                    familyHistory: [this.START.family],
                    bankHistory: [this.START.bank],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed MIDDLING / neutral — NOT textbook-correct. Click-through must not auto-win.
                state.decisions = {
                    diag: `income`,         // wrong sibling default (income-statement myopia)
                    gap: 22000,             // CapEx only — misses the working-capital trap
                    govhonesty: 50,
                    debt: 14000,
                    lease: 4000,
                    retained: 4200,
                    equity: 6000,
                    policy: `suspend`,      // not the staged-target best answer
                    bridge: `none`,         // no bridge for the dependent shareholder
                    freed: 3000,
                    board: `onefriend`,     // cosmetic, not the independent-board best answer
                    founder: `veto`,        // keeps the informal veto (cosmetic governance)
                    pitch: `financeonly`,   // splits governance from the numbers
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const diag = document.getElementById(`diagInput`);
                const gap = document.getElementById(`gapInput`);
                const hon = document.getElementById(`govhonestyInput`);
                if (diag) decisions.diag = diag.value;
                if (gap) decisions.gap = parseFloat(gap.value);
                if (hon) decisions.govhonesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.gap) || decisions.gap < 0 || decisions.gap > 60000) {
                    warn(`warn_gap_range`); return false;
                }
                if (!Number.isFinite(decisions.govhonesty) || decisions.govhonesty < 0 || decisions.govhonesty > 100) {
                    warn(`warn_govhonesty_range`); return false;
                }
            } else if (round === 2) {
                const debt = document.getElementById(`debtInput`);
                const lease = document.getElementById(`leaseInput`);
                const retained = document.getElementById(`retainedInput`);
                const equity = document.getElementById(`equityInput`);
                if (debt) decisions.debt = parseFloat(debt.value);
                if (lease) decisions.lease = parseFloat(lease.value);
                if (retained) decisions.retained = parseFloat(retained.value);
                if (equity) decisions.equity = parseFloat(equity.value);
                const parts = [decisions.debt, decisions.lease, decisions.retained, decisions.equity];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_mix_negative`); return false;
                }
                const total = decisions.debt + decisions.lease + decisions.retained + decisions.equity;
                // Must come within COP$2.000M of the requirement (a fundable plan).
                if (total < this.REQUIREMENT - 2000) {
                    warn(`warn_mix_short`); return false;
                }
            } else if (round === 3) {
                const policy = document.getElementById(`policyInput`);
                const bridge = document.getElementById(`bridgeInput`);
                const freed = document.getElementById(`freedInput`);
                if (policy) decisions.policy = policy.value;
                if (bridge) decisions.bridge = bridge.value;
                if (freed) decisions.freed = parseFloat(freed.value);
                if (!Number.isFinite(decisions.freed) || decisions.freed < 0 || decisions.freed > 6000) {
                    warn(`warn_freed_range`); return false;
                }
            } else if (round === 4) {
                const board = document.getElementById(`boardInput`);
                const founder = document.getElementById(`founderInput`);
                const pitch = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (board) decisions.board = board.value;
                if (founder) decisions.founder = founder.value;
                if (pitch) decisions.pitch = pitch.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let liqDelta = 0, healthDelta = 0, familyDelta = 0, bankDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // DIAGNOSIS — read the balance sheet past the income statement.
                // Correct: cashgap (working-capital trap + CapEx drain a profitable firm).
                if (d.diag === `cashgap`) {
                    liqDelta += 14; bankDelta += 8; healthDelta += 4; coachKey = `coach_r1_cashgap`;
                } else if (d.diag === `income`) {
                    // Common Error 1 — income-statement myopia. Worst diagnosis.
                    liqDelta -= 12; bankDelta -= 6; ds.insolvent = true; coachKey = `coach_r1_income`;
                } else if (d.diag === `growth`) {
                    liqDelta -= 10; bankDelta -= 4; ds.insolvent = true; coachKey = `coach_r1_growth`;
                } else { // profit — confuses margin with liquidity
                    liqDelta -= 6; bankDelta -= 2; coachKey = `coach_r1_profit`;
                }

                // SIZE THE GAP — true requirement ≈ 28.200 (CapEx 22.000 + WC trap 6.200).
                const err = Math.abs(d.gap - this.REQUIREMENT);
                if (err <= 1500) {
                    liqDelta += 12; bankDelta += 6;
                    if (d.diag === `cashgap`) coachKey = `coach_r1_sharp`;
                } else if (d.gap <= this.CAPEX + 1000 && d.gap >= this.CAPEX - 1000) {
                    // Sized CapEx only — missed the working-capital trap entirely.
                    liqDelta -= 8; bankDelta -= 2; coachKey = `coach_r1_capexonly`;
                } else if (err <= 4000) {
                    liqDelta += 4; bankDelta += 2;
                } else {
                    liqDelta -= 4;
                }

                // GOVERNANCE HONESTY — naming governance as a financial variable.
                if (d.govhonesty >= 65) { bankDelta += 8; familyDelta += 2; }
                else if (d.govhonesty <= 25) { bankDelta -= 8; coachKey = `coach_r1_lowhonesty`; }
                else { bankDelta += 2; }

                summaryKey = (d.diag === `cashgap` && Math.abs(d.gap - this.REQUIREMENT) <= 1500) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // FINANCING MIX — fund ≈28.200 without breaching the 3.0x covenant.
                const debt = d.debt, lease = d.lease, retained = d.retained, equity = d.equity;
                const total = debt + lease + retained + equity;
                ds.funded = Math.round(total);

                // Pro-forma leverage from NEW debt on top of the 1.1x base.
                ds.leverage = Math.round((this.START_LEVERAGE + (debt / 1000) * this.LEV_PER_1000) * 100) / 100;

                // Covenant test — the binding financial constraint.
                if (ds.leverage > this.COVENANT) {
                    // Common Error 2 — control-at-all-costs all-debt funding breaches the covenant.
                    ds.covenantBreach = true;
                    healthDelta -= 18; bankDelta -= 14; liqDelta -= 4; coachKey = `coach_r2_breach`;
                } else if (ds.leverage > this.COVENANT - 0.3) {
                    // Razor-thin headroom — one bad quarter and it breaches.
                    healthDelta -= 4; bankDelta -= 2; coachKey = `coach_r2_thin`;
                } else {
                    healthDelta += 8; bankDelta += 4;
                }

                // Funding the gap improves liquidity coverage proportionally.
                const coverage = Math.min(1, total / this.REQUIREMENT);
                liqDelta += Math.round(coverage * 26);
                if (total < this.REQUIREMENT - 2000) { liqDelta -= 10; coachKey = `coach_r2_underfund`; }

                // Cheap, control-preserving levers (lease, sized debt, retained) reward health/ROE.
                if (lease >= 3000) { healthDelta += 4; }
                if (retained >= 3000) { healthDelta += 5; familyDelta -= 3; } // retaining funds growth but tenses family
                else if (retained <= 500) { healthDelta -= 4; } // ignoring the cheapest internal lever

                // Reflexive dilution — Common Error 5: heavy outside equity before exhausting cheaper levers.
                const cheaperUsed = debt >= 8000 || lease >= 3000 || retained >= 3000;
                if (equity >= 12000 && !cheaperUsed) {
                    familyDelta -= 14; bankDelta -= 2; coachKey = `coach_r2_dilution`;
                } else if (equity >= 12000) {
                    familyDelta -= 8; coachKey = `coach_r2_overequity`;
                } else if (equity > 0 && equity <= 8000 && cheaperUsed) {
                    bankDelta += 4; healthDelta += 2; // measured, balance-sheet-strengthening minority stake
                }

                // A balanced, covenant-safe, sequenced mix is the concept-correct answer.
                const balanced = !ds.covenantBreach && total >= this.REQUIREMENT - 2000 &&
                    debt >= 8000 && debt <= 18000 && lease >= 2000 && retained >= 2000 && equity <= 9000;
                if (balanced) { healthDelta += 6; bankDelta += 6; coachKey = `coach_r2_balanced`; }

                summaryKey = ds.covenantBreach ? `sum_r2_breach` : (balanced ? `sum_r2_good` : `sum_r2_weak`);
            } else if (round === 3) {
                // DIVIDEND POLICY + DEPENDENT-SHAREHOLDER BRIDGE.
                switch (d.policy) {
                    case `target`: healthDelta += 8; familyDelta += 10; liqDelta += 4; coachKey = `coach_r3_target`; break;
                    case `residual`: healthDelta += 6; familyDelta -= 2; liqDelta += 3; coachKey = `coach_r3_residual`; break;
                    case `suspend`: healthDelta += 4; familyDelta -= 10; coachKey = `coach_r3_suspend`; break;
                    case `keep`: healthDelta -= 12; liqDelta -= 8; coachKey = `coach_r3_keep`; break; // starves growth
                }

                // The dependent abroad-based sibling who threatens to block any cut.
                switch (d.bridge) {
                    case `bridge`: familyDelta += 18; bankDelta += 4; coachKey = (d.policy === `target`) ? `coach_r3_bridgeright` : coachKey; break;
                    case `buyout`: familyDelta += 2; healthDelta -= 8; liqDelta -= 6; coachKey = `coach_r3_buyout`; break; // expensive cash-out mid-squeeze
                    case `none`: familyDelta -= 16; coachKey = `coach_r3_none`; break;     // Common Error 3 — voted down
                    case `ignore`: familyDelta -= 18; bankDelta -= 4; coachKey = `coach_r3_ignore`; break;
                }

                // Cash freed for reinvestment — current dividend ≈6.000/yr.
                if (d.freed >= 2500 && d.freed <= 4500) { liqDelta += 8; healthDelta += 4; }
                else if (d.freed > 4500) { liqDelta += 6; familyDelta -= 6; } // over-retain, family strained
                else { liqDelta += 2; healthDelta -= 2; } // barely reinvests

                summaryKey = (d.policy === `target` && d.bridge === `bridge`) ? `sum_r3_good`
                    : ((d.bridge === `none` || d.bridge === `ignore`) ? `sum_r3_blocked` : `sum_r3_weak`);
            } else if (round === 4) {
                // GOVERNANCE REFORM + INTEGRATED PITCH.
                switch (d.board) {
                    case `independent`: bankDelta += 16; healthDelta += 4; coachKey = `coach_r4_independent`; break;
                    case `advisory`: bankDelta += 4; coachKey = `coach_r4_advisory`; break;
                    case `onefriend`: bankDelta -= 2; coachKey = `coach_r4_onefriend`; break;
                    case `paper`: bankDelta -= 12; coachKey = `coach_r4_paper`; break; // Common Error 4 — cosmetic
                }

                // Founder transition — genuine separation vs preserving the informal veto.
                switch (d.founder) {
                    case `defined`: bankDelta += 10; familyDelta += 6; coachKey = (d.board === `independent`) ? `coach_r4_definedboard` : coachKey; break;
                    case `figurehead`: bankDelta += 2; familyDelta -= 12; coachKey = `coach_r4_figurehead`; break; // abrupt, breaks family
                    case `veto`: bankDelta -= 12; coachKey = `coach_r4_veto`; break; // cosmetic — veto survives under the chart
                }

                // The integrated pitch to the credit committee and retailer.
                switch (d.pitch) {
                    case `integrated`: bankDelta += 10; liqDelta += 4; healthDelta += 2; coachKey = (d.board === `independent` && d.founder === `defined`) ? `coach_r4_integrated` : coachKey; break;
                    case `financeonly`: bankDelta -= 6; coachKey = `coach_r4_financeonly`; break;
                    case `prestige`: bankDelta -= 8; coachKey = `coach_r4_prestige`; break;
                }

                // Conviction on long-run family wealth nudges family trust.
                familyDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.board === `independent` && d.founder === `defined` && d.pitch === `integrated`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas, clamp 0..100.
            ds.liquidity = Math.max(0, Math.min(100, ds.liquidity + liqDelta));
            ds.health = Math.max(0, Math.min(100, ds.health + healthDelta));
            ds.family = Math.max(0, Math.min(100, ds.family + familyDelta));
            ds.bank = Math.max(0, Math.min(100, ds.bank + bankDelta));

            ds.liquidityHistory.push(Math.round(ds.liquidity));
            ds.healthHistory.push(Math.round(ds.health));
            ds.familyHistory.push(Math.round(ds.family));
            ds.bankHistory.push(Math.round(ds.bank));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist the composite where the gradebook/score resolver reads it
            // (domainState.performance.overallScore first, then a top-level score/netWorth).
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = { overallScore: _score };

            return {
                period: state.currentPeriod,
                liquidity: Math.round(ds.liquidity),
                liquidityDelta: Math.round(liqDelta),
                health: Math.round(ds.health),
                healthDelta: Math.round(healthDelta),
                family: Math.round(ds.family),
                familyDelta: Math.round(familyDelta),
                bank: Math.round(ds.bank),
                bankDelta: Math.round(bankDelta),
                leverage: ds.leverage,
                funded: ds.funded,
                covenantBreach: ds.covenantBreach,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

