                hon.addEventListener(`input`, function() { honReadout.textContent = hon.value; });
            }

            // Round 2 — live financing-mix total.
            const mixIds = [`debtInput`, `leaseInput`, `retainedInput`, `equityInput`];
            const mixReadout = document.getElementById(`mixReadout`);
            const recompute = function() {
                let total = 0;
                mixIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (mixReadout) mixReadout.textContent = `COP$` + self._fmt(total) + `M`;
                const readoutRow = document.querySelector(`.familyfin-alloc-readout`);
                if (readoutRow) readoutRow.style.color = (total < self.REQUIREMENT - 2000) ? `#c0392b` : ``;
            };
            mixIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        _toneCard(selector, value, goodAt, warnBelow) {
            const card = document.querySelector(selector);
