        // v1.1.0: single source of truth for the composite (verbatim v1.0.0 formula).
        _composite(ds) {
            const liquidity = Math.round(ds.liquidity);
            const health = Math.round(ds.health);
            const family = Math.round(ds.family);
            const bank = Math.round(ds.bank);
            let composite = Math.round(liquidity * 0.25 + health * 0.25 + family * 0.25 + bank * 0.25);
            if (ds.covenantBreach) composite = Math.max(0, composite - 15);
            return composite;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const liquidity = Math.round(ds.liquidity);
            const health = Math.round(ds.health);
            const family = Math.round(ds.family);
            const bank = Math.round(ds.bank);

            // Composite weights the four KPIs evenly; covenant breach is a hard penalty.
            let composite = this._composite(ds);

            const funded = ds.funded >= this.REQUIREMENT - 2000;
            const bankable = bank >= 60 && !ds.covenantBreach;
            const familyHeld = family >= 55;

            let performance = `Deal Lost`, performanceKey = `grade_lost`;
            if (composite >= 72 && funded && bankable && familyHeld && health >= 55) { performance = `Deal Locked — Built to Scale`; performanceKey = `grade_locked`; }
            else if (composite >= 60 && funded && bank >= 50) { performance = `Financed but Fragile`; performanceKey = `grade_fragile`; }
            else if (ds.covenantBreach) { performance = `Covenant Breach`; performanceKey = `grade_covenant`; }
            else if (family < 40) { performance = `Voted Down by the Family`; performanceKey = `grade_voteddown`; }
            else if (liquidity < 40) { performance = `Still Cash-Constrained`; performanceKey = `grade_cashconstrained`; }
            const met = funded && !ds.covenantBreach && bank >= 50 && composite >= 60;

            const insights = [];
            if (composite >= 72 && funded && bankable && familyHeld) insights.push(window.mySimulation.t(`insight_locked`));
            else if (ds.covenantBreach) insights.push(window.mySimulation.t(`insight_covenant`));
            else if (family < 40) insights.push(window.mySimulation.t(`insight_family`));
            else if (!funded) insights.push(window.mySimulation.t(`insight_unfunded`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (liquidity < 45) insights.push(window.mySimulation.t(`insight_liquidity`));
            if (bank < 45) insights.push(window.mySimulation.t(`insight_governance`));
            if (composite >= 72 && funded && bankable && familyHeld) insights.push(window.mySimulation.t(`insight_integrated`));

            return {
                liquidity: liquidity,
                health: health,
                family: family,
                bank: bank,
                leverage: ds.leverage,
                covenantBreach: ds.covenantBreach,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            const s = summary || {};
            const raw = (s.composite != null) ? s.composite : (s.overallScore != null ? s.overallScore : 0);
            const score = Math.max(0, Math.min(100, Math.round(Number(raw) || 0)));
            const grade = s.performanceKey ? t(s.performanceKey) : (s.performance || ``);
            const badge = s.met
                ? `<span class="ffsim-cm-badge ffsim-cm-badge-ok">${t(`cm_targets_met`)}</span>`
                : `<span class="ffsim-cm-badge ffsim-cm-badge-miss">${t(`cm_targets_missed`)}</span>`;
            const kpi = (k, v, suf) => `<div class="ffsim-cm-kpi"><div class="ffsim-cm-kpi-val">${(v != null ? v : `—`)}${suf || ``}</div><div class="ffsim-cm-kpi-lbl">${t(k)}</div></div>`;
            const ins = Array.isArray(s.insights) ? s.insights : [];
            const insHtml = ins.length
                ? `<div class="ffsim-cm-insights"><div class="ffsim-cm-ins-h">${t(`cm_insights`)}</div><ul>${ins.map((i) => `<li>${i}</li>`).join(``)}</ul></div>`
                : ``;
            return `
                <div class="ffsim-cm">
                    <div class="ffsim-cm-title">${t(`cm_title`)}</div>
                    <div class="ffsim-cm-scorewrap">
                        <div class="ffsim-cm-score">${score}<span class="ffsim-cm-score-max">/100</span></div>
                        <div class="ffsim-cm-grade">${grade}</div>
                        <div class="ffsim-cm-badges">${badge}</div>
