                        ${kpi(`cm_kpi_health`, s.health, ``)}
                        ${kpi(`cm_kpi_family`, s.family, ``)}
                        ${kpi(`cm_kpi_bank`, s.bank, ``)}
                    </div>
                    ${insHtml}
                </div>`;
        }

